/* 00000868-00000ACC       .text phase_1__FP14daNpcAuction_c */
static cPhs_State phase_1(daNpcAuction_c* i_this) {
    // fakematch (found by permuter): rndKind (assignment-in-expression copy of kind) and the npcNo copy
    // "no" only steer demo register allocation (minKind needs one fewer interference); retail is unaffected.
    u8 rndKind;
    u8 no;
    fopAcM_ct(i_this, daNpcAuction_c);

    daAuction_c* auction;
    if (!fopAcM_SearchByName(fpcNm_AUCTION_e, (fopAc_ac_c**)&auction)) {
        return cPhs_INIT_e;
    }
    if (auction == NULL) {
        return cPhs_INIT_e;
    }

    u8 prmNo = i_this->getPrmNpcNo();
    u8 npcNo = auction->getAucNpcNo(prmNo);
    no = npcNo;
    i_this->setNpcNo(npcNo);

    if (!auction->setNpcID(npcNo, fopAcM_GetID(i_this))) {
        return cPhs_INIT_e;
    }

    int minKind = l_kind_max[no][0];
    int maxKind = l_kind_max[npcNo][1];
    u8 kind;
    if (npcNo == 2 || npcNo == 3) {
        if (auction->getKind(0) == 0xFF) {
            kind = minKind + i_this->getRand(maxKind - minKind + 1);
            auction->setKind(0, kind);
        } else {
            kind = (rndKind = minKind + i_this->getRand(maxKind - minKind + 1));
            if (rndKind == auction->getKind(0)) {
                if (rndKind == (u8)maxKind) {
                    kind--;
                } else {
                    kind++;
                }
            }
        }
    } else if (npcNo == 4 || npcNo == 5) {
        if (auction->getKind(1) == 0xFF) {
            kind = minKind + i_this->getRand(maxKind - minKind + 1);
            auction->setKind(1, kind);
        } else {
            kind = minKind + i_this->getRand(maxKind - minKind + 1);
            if (kind == auction->getKind(1)) {
                if (kind == (u8)maxKind) {
                    kind--;
                } else {
                    kind++;
                }
            }
        }
    } else {
        kind = minKind + i_this->getRand(maxKind - minKind + 1);
    }

    i_this->setMdlNo(kind);
    auction->setAucMdlNo(npcNo, kind);
    i_this->setBtpNo(l_btp_ix_tbl[kind]);
    i_this->setBmtNo(l_bmt_ix_tbl[kind]);
    return cPhs_NEXT_e;
}

/* 00000ACC-00000B4C       .text phase_2__FP14daNpcAuction_c */
static cPhs_State phase_2(daNpcAuction_c* i_this) {
    cPhs_State phase_state = dComIfG_resLoad(i_this->getPhaseP(), l_arcname_tbl[i_this->getMdlNo()]);
    if (phase_state == cPhs_COMPLEATE_e) {
        if (fopAcM_entrySolidHeap(i_this, CheckCreateHeap, 0x10000)) {
            return i_this->createInit();
        } else {
#if VERSION > VERSION_DEMO
            i_this->mpMorf = NULL;
#endif
            return cPhs_ERROR_e;
        }
    }
    return phase_state;
}

inline cPhs_State daNpcAuction_c::_create() {
    static cPhs__Handler l_method[] = {
        (cPhs__Handler)phase_1,
        (cPhs__Handler)phase_2,
        NULL,
    };
    return dComLbG_PhaseHandler(&mPhs2, l_method, this);
}

/* 00000B4C-00000E74       .text createHeap__14daNpcAuction_cFv */
BOOL daNpcAuction_c::createHeap() {
    J3DModelData* modelData = (J3DModelData*)dComIfG_getObjectIDRes(l_arcname_tbl[mMdlNo], l_bmd_ix_tbl[mMdlNo]);
    mpMorf = new mDoExt_McaMorf(
        modelData,
        NULL, NULL,
        (J3DAnmTransform*)dComIfG_getObjectIDRes(l_arcname_tbl[mMdlNo], l_bck_ix_tbl[mMdlNo][mAnmNo]),
        J3DFrameCtrl::EMode_LOOP, 1.0f, 0, -1, 1,
        NULL,
        0x80000,
        l_diff_flag_tbl[mMdlNo]
    );

    if (mpMorf == NULL || mpMorf->getModel() == NULL) {
        return FALSE;
    }

    if (l_head_bmd_ix_tbl[mMdlNo] >= 0) {
        J3DModelData* headModelData = (J3DModelData*)dComIfG_getObjectIDRes(l_arcname_tbl[mMdlNo], l_head_bmd_ix_tbl[mMdlNo]);
        mpHeadModel = mDoExt_J3DModel__create(headModelData, 0x80000, 0x15020022);
        if (mpHeadModel == NULL) {
            return FALSE;
        }
    }

    m_jnt.setHeadJntNum(modelData->getJointName()->getIndex("head"));
    JUT_ASSERT(DEMO_SELECT(0x45B, 0x45C), m_jnt.getHeadJntNum() >= 0);
    m_jnt.setBackboneJntNum(modelData->getJointName()->getIndex("backbone"));
    JUT_ASSERT(DEMO_SELECT(0x45F, 0x460), m_jnt.getBackboneJntNum() >= 0);

    if (!initTexPatternAnm(false)) {
        return FALSE;
    }

    for (u16 i = 0; i < modelData->getJointNum(); i++) {
        if (i == m_jnt.getHeadJntNum() || i == m_jnt.getBackboneJntNum()) {
            modelData->getJointNodePointer(i)->setCallBack(l_node_call_back_tbl[mNpcNo]);
        }
    }
    mpMorf->getModel()->setUserArea((u32)this);
    mAcchCir.SetWall(30.0f, 30.0f);
    mObjAcch.Set(fopAcM_GetPosition_p(this), fopAcM_GetOldPosition_p(this), this, 1, &mAcchCir, fopAcM_GetSpeed_p(this), fopAcM_GetAngle_p(this), fopAcM_GetShapeAngle_p(this));
    return TRUE;
}

