/* 00001270-000013FC       .text eventMove__14daNpcAuction_cFv */
void daNpcAuction_c::eventMove() {
    if (dComIfGp_evmng_endCheck("AUCTION_GET_ITEM") ||
        dComIfGp_evmng_endCheck("AUCTION_NO_ITEM") ||
        dComIfGp_evmng_endCheck("AUCTION_END2"))
    {
        mMaxAttnDistXZ = 200.0f;
    } else if (dComIfGp_evmng_endCheck("AUCTION_TALK_XY")) {
        if (m745 == 0) {
            dComIfGp_event_reset();
        } else if (mNpcNo == 0) {
            daAuction_c* auction = (daAuction_c*)fopAcM_SearchByName(fpcNm_AUCTION_e);
            if (auction != NULL) {
                if (m745 == 1) {
                    auction->setStart(1);
                } else if (m745 == 2) {
                    auction->setStart(2);
                    auction->setItemNo(m743);
                }
            }
        }
        m744 = 1;
        mTalking = 0;
    } else {
        bool attn = mEventCut.getAttnFlag();
        if (mEventCut.cutProc()) {
            if (!mEventCut.getAttnFlag()) {
                mEventCut.setAttnFlag(attn);
            }
        } else {
            privateCut();
            if (mNpcNo == 7) {
                setAnmFromMsgTag();
            }
        }
    }
}

/* 000013FC-00001548       .text privateCut__14daNpcAuction_cFv */
void daNpcAuction_c::privateCut() {
    static char* cut_name_tbl[] = {"MAIN", "MES_SET"};
    int staffIdx = dComIfGp_evmng_getMyStaffId(l_npc_staff_id[mNpcNo]);
    if (staffIdx != -1) {
        mCutAct = dComIfGp_evmng_getMyActIdx(staffIdx, cut_name_tbl, 2, 1, 0);
        if (mCutAct == -1) {
            dComIfGp_evmng_cutEnd(staffIdx);
        } else {
            if (dComIfGp_evmng_getIsAddvance(staffIdx)) {
                switch (mCutAct) {
                case 0:
                    eventMainInit();
                    break;
                case 1:
                    eventMesSetInit(staffIdx);
                    break;
                }
            }
            bool done;
            switch (mCutAct) {
            case 0:
                done = eventMain();
                break;
            case 1:
                done = eventMesSet();
                break;
            default:
                done = true;
                break;
            }
            if (done) {
                dComIfGp_evmng_cutEnd(staffIdx);
            }
        }
    }
}

