/* 00001554-00001888       .text eventMain__14daNpcAuction_cFv */
bool daNpcAuction_c::eventMain() {
    daAuction_c* auction = (daAuction_c*)fopAcM_SearchByName(fpcNm_AUCTION_e);
    if (auction->isAucBet2()) {
        if ((m747 & 0x08) == 0) {
            setAnm2(3, 2, 8.0f);
            m747 |= 0x08;
        }
    } else if (mNpcNo == auction->getAnmNpcNo()) {
        if (auction->isAucBet()) {
            if ((m747 & 0x04) == 0) {
                setAnm2(2, 2, 8.0f);
                m747 |= 0x04;
            }
        } else if (auction->isAucBetA()) {
            if ((m747 & 0x10) == 0) {
                setAnm2(4, 2, 8.0f);
                m747 |= 0x10;
            }
        } else if (auction->isAucJikkyou()) {
            if ((m747 & 0x40) == 0) {
                setAnm2(6, 2, 8.0f);
                m747 |= 0x40;
            }
        } else if (auction->isAucGet()) {
            if ((m747 & 0x20) == 0) {
                setAnm2(5, 2, 8.0f);
                m747 |= 0x20;
            }
            m749 = 0;
        } else {
            m747 = 0;
            if (mAnmNo != 0) {
                setAnm2(0, 2, 8.0f);
            }
        }
    } else {
        m747 = 0;
        if (mAnmNo != 0) {
            setAnm2(0, 2, 8.0f);
        }
    }

    if (auction->isAucBet2()) {
        if (mpEmitter == NULL) {
            mpEmitter = dComIfGp_particle_set(
                dPa_name::ID_IT_SN_MD_PIYOPIYO00, &current.pos, NULL, NULL, 0xFF, NULL,
                fopAcM_GetRoomNo(this), &tevStr.mColorK0, &tevStr.mColorK0
            );
            if (mpEmitter != NULL) {
                mpEmitter->becomeImmortalEmitter();
            }
        }
        if (mpEmitter != NULL) {
            MTXCopy(mpMorf->getModel()->getAnmMtx(m_jnt.getHeadJntNum()), *calc_mtx);
            mDoMtx_ZrotM(*calc_mtx, -0x4000);
            mDoMtx_stack_c::transS(0.0f, l_npc_dat[mMdlNo].field_0x2C, 0.0f);
            mDoMtx_concat(*calc_mtx, mDoMtx_stack_c::now, *calc_mtx);
            mpEmitter->setGlobalRTMatrix(*calc_mtx);
        }
    } else {
        clrEmitter();
    }
    return FALSE;
}

