/* 00001CD4-00001F04       .text getMsg__14daNpcAuction_cFv */
u32 daNpcAuction_c::getMsg() {
    u32 msgNo;
    if (mNpcNo == 0) {
        if (dComIfGp_event_chkTalkXY()) {
            u8 itemNo = dComIfGp_event_getPreItemNo();
            if (itemNo == dItemNo_POSTMAN_STATUE_e) {
                if (!dComIfGs_isEventBit(dSv_event_flag_c::UNK_1008)) {
                    msgNo = 0x27EB;
                    m743 = 0;
                } else {
                    msgNo = 0x27F7;
                }
            } else if (itemNo == dItemNo_SHOP_GURU_STATUE_e) {
                if (!dComIfGs_isEventBit(dSv_event_flag_c::UNK_1004)) {
                    msgNo = 0x27EB;
                    m743 = 1;
                } else {
                    msgNo = 0x27F7;
                }
            } else {
                msgNo = 0x27EA;
            }
        } else if (dComIfGs_isEventBit(dSv_event_flag_c::ENDLESS_NIGHT) &&
                   !dComIfGs_checkGetItem(dItemNo_PEARL_NAYRU_e))
        {
            msgNo = 0x27F8;
        } else if (dComIfGs_isEventBit(dSv_event_flag_c::UNK_1002)) {
            if (dComIfGs_isEventBit(dSv_event_flag_c::UNK_0F01) &&
                dComIfGs_isEventBit(dSv_event_flag_c::UNK_1080) &&
                dComIfGs_isEventBit(dSv_event_flag_c::UNK_1040) &&
                dComIfGs_isEventBit(dSv_event_flag_c::UNK_1020))
            {
                msgNo = 0x27F0;
            } else {
                msgNo = 0x27DB;
            }
        } else {
            dComIfGs_onEventBit(dSv_event_flag_c::UNK_1002);
            msgNo = 0x27DA;
        }
    } else if (mNpcNo == 6) {
        msgNo = 0x1D35;
    } else {
        daAuction_c* auction = (daAuction_c*)fopAcM_SearchByName(fpcNm_AUCTION_e);
        u8 winner = auction->getNpcNo();
        if (winner == 0) {
            msgNo = l_npc_msg_id[mMdlNo][0];
        } else if (winner == mNpcNo) {
            msgNo = l_npc_msg_id[mMdlNo][1];
        } else {
            msgNo = l_npc_msg_id[mMdlNo][2];
        }
    }
    return msgNo;
}

