/* 00002118-00002488       .text lookBack__14daNpcAuction_cFv */
void daNpcAuction_c::lookBack() {
    f32 attnY = l_npc_dat[mMdlNo].m04;
    s16 maxVel = l_npc_dat[mMdlNo].mMaxHeadTurnVel;
    s16 defaultY = current.angle.y;
    cXyz* dstPosP = NULL;
    cXyz dstPos;
    bool noTurn = true;

    if (m749 != 0) {
        fopAc_ac_c* auction = fopAcM_SearchByName(fpcNm_AUCTION_e);
        if (auction != NULL) {
            if (eyePos.x != auction->eyePos.x || eyePos.y != auction->eyePos.y || eyePos.z != auction->eyePos.z) {
                dstPos = auction->eyePos;
                dstPosP = &dstPos;
            }
        }
    } else if (mEventCut.getAttnFlag()) {
        m_jnt.setTrn();
        dstPos = mEventCut.getAttnPos();
        dstPosP = &dstPos;
        noTurn = false;
        if (m73D == 0) {
            m73D = 1;
        }
    } else {
        fopAc_ac_c* player = dComIfGp_getLinkPlayer();
        f32 maxDist = mMaxAttnDistXZ;
        int maxAng = l_npc_dat[mMdlNo].mMaxAttnAngleY;
        int lim0 = 0x4000;
        f32 dist;
        s16 ang;
        dNpc_calc_DisXZ_AngY(current.pos, player->current.pos, &dist, &ang);
        if (m73D != 0) {
            maxDist += 40.0f;
            lim0 = 0x471C;
            maxAng += 0x71C;
        }
        ang -= current.angle.y;
        if (maxDist > dist && lim0 > abs(ang)) {
            dstPos = dNpc_playerEyePos(attnY);
            dstPosP = &dstPos;
            noTurn = true;
            if (m73D == 0) {
                m73D = 1;
            }
        } else if (maxDist > dist && maxAng > abs(ang)) {
            if (mTalking != 0) {
                dstPos = dNpc_playerEyePos(attnY);
                dstPosP = &dstPos;
                noTurn = false;
                m_jnt.setTrn();
            }
            if (m73D == 0) {
                m73D = 1;
            }
        } else {
            m73D = 0;
            if (mNpcNo == 0) {
                defaultY = home.angle.y;
                noTurn = false;
                m_jnt.setTrn();
            }
        }
    }

    if (mTalking != 0) {
        noTurn = false;
        m_jnt.setTrn();
    }
    if (m_jnt.trnChk()) {
        s16 t = mEventCut.getTurnSpeed();
        if (t != 0) {
            maxVel = t;
        }
        cLib_addCalcAngleS2(&mCurrentTurnSpeed, maxVel, 4, 0x800);
    } else {
        mCurrentTurnSpeed = 0;
    }
    m_jnt.lookAtTarget(&current.angle.y, dstPosP, eyePos, defaultY, mCurrentTurnSpeed, noTurn);
    shape_angle = current.angle;
}

/* 00002488-000025AC       .text initTexPatternAnm__14daNpcAuction_cFb */
